module TopModule (
    input  logic clk,
    input  logic reset,
    input  logic data,
    output logic start_shifting
);

    typedef enum logic [2:0] {
        IDLE  = 3'd0,
        S1    = 3'd1,
        S11   = 3'd2,
        S110  = 3'd3,
        FOUND = 3'd4
    } state_t;

    state_t state, next_state;

    always_ff @(posedge clk) begin
        if (reset) begin
            state <= IDLE;
        end else begin
            state <= next_state;
        end
    end

    always_comb begin
        next_state = state;
        case (state)
            IDLE: begin
                if (data) next_state = S1;
                else      next_state = IDLE;
            end
            S1: begin
                if (data) next_state = S11;
                else      next_state = IDLE;
            end
            S11: begin
                if (data) next_state = S11;
                else      next_state = S110;
            end
            S110: begin
                if (data) next_state = FOUND;
                else      next_state = IDLE;
            end
            FOUND: begin
                next_state = FOUND;
            end
            default: begin
                next_state = IDLE;
            end
        endcase
    end

    assign start_shifting = (state == FOUND);

endmodule

